def _deep_merge(base: dict, override: dict) -> dict:
    out = copy.deepcopy(base)
    for key, value in (override or {}).items():
        if isinstance(value, dict) and isinstance(out.get(key), dict):
            out[key] = _deep_merge(out[key], value)
        else:
            out[key] = value
    return out


def config_path() -> Path:
    return Path(os.environ.get("WT_CONFIG") or (ROOT / "config.json"))


def load_config() -> dict:
    path = config_path()
    override = {}
    if path.is_file():
        with open(path, "r", encoding="utf-8-sig") as fh:
            override = json.load(fh)
    cfg = _deep_merge(DEFAULTS, override)
    from .policy import apply_policy

    cfg = apply_policy(cfg, override)
    data_dir = os.environ.get("WT_DATA") or cfg.get("data_dir") or str(ROOT / "data")
    cfg["_data_dir"] = str(Path(data_dir).expanduser().resolve())
    cfg["_root"] = str(ROOT)
    cfg["_config_path"] = str(path)
    return cfg


def data_paths(cfg: dict) -> dict:
    data = Path(cfg["_data_dir"])
    paths = {
        "data": data,
        "db": data / "worktime.db",
        "logs": data / "logs",
        "reports": data / "reports",
        "exports": data / "exports",
    }
    for p in paths.values():
        if p.suffix:  # file
            p.parent.mkdir(parents=True, exist_ok=True)
        else:
            p.mkdir(parents=True, exist_ok=True)
    return paths
